                    if grid[r][c] == val:
                        unique_pos = (r, c)
                        break
        elif cnt > 1:
            for r in range(len(grid)):
                for c in range(len(grid[0])):
                    if grid[r][c] == val:
                        pair_positions.append((r, c))

    if not unique_pos:
