    u_r, u_c = unique_pos

    res = [row[:] for row in grid]
    res[u_r][u_c] = 4

    pair_set = set(pair_positions)

    # Create filled set
    filled = set([(r, u_c) for r in range(len(grid))])

    # Check all 4 directions
    def fill_up():
