            if (r, u_c) in pair_set or (r, u_c) in filled:
                break
            res[r][u_c] = unique_color
            filled.add((r, u_c))

    def fill_down():
        for r in range(u_r + 1, len(grid)):
            if (r, u_c) in pair_set or (r, u_c) in filled:
                break
            res[r][u_c] = unique_color
            filled.add((r, u_c))

